def AND(a, b): return a & b
def OR(a, b): return a | b
def XOR(a, b): return a ^ b


def half_adder(a, b):
    return XOR(a, b), AND(a, b)          # (sum, carry)


def full_adder(a, b, carry_in):
    s1, c1 = half_adder(a, b)
    s2, c2 = half_adder(s1, carry_in)
    return s2, OR(c1, c2)


print("half adder: a b -> sum carry")
for a in (0, 1):
    for b in (0, 1):
        print(f"  {a} {b} -> {half_adder(a, b)[0]}   {half_adder(a, b)[1]}")


def add_bits(x, y, width=8):
    result, carry = 0, 0
    for i in range(width):
        bit, carry = full_adder((x >> i) & 1, (y >> i) & 1, carry)
        result |= bit << i
    return result, carry


print()
for x, y in [(5, 3), (45, 27), (200, 100)]:
    total, carry = add_bits(x, y)
    print(f"{x:08b} + {y:08b} = {total:08b} carry {carry}  ({x} + {y} -> {total})")

ok = all(add_bits(x, y)[0] == (x + y) % 256 for x in range(256) for y in range(256))
print("all 65,536 byte pairs correct:", ok)

